fn remove_duplicates(nums: &Vec<i32>) -> usize {
    // Since the array is sorted (non-decreasing), duplicates appear consecutively.
    // We can count distinct values by iterating once and counting how many times
    // the current value differs from the previous value.
    if nums.is_empty() {
        return 0;
    }

    let mut count = 1; // at least one distinct value if array is non-empty
    for i in 1..nums.len() {
        if nums[i] != nums[i - 1] {
            count += 1;
        }
    }
    count
}